<script>let w = $state(0); let scroll = $state(0); let online = $state(true); let active = $state(null); let visibility = $state("visible"); let ratio = $state(1);</script><svelte:window bind:innerWidth={w} bind:scrollY={scroll} bind:online={online} bind:devicePixelRatio={ratio}/><svelte:document bind:activeElement={active} bind:visibilityState={visibility}/><p>{w} {scroll} {online} {active} {visibility} {ratio}</p>